async function fetchUsers() {
  try {
    const response = await fetch('https://example.com/users');

    if (!response.ok) {
      throw new Error(`HTTP error: ${response.status}`);
    }

    const users = await response.json();

    return users;
  } catch (error) {
    console.error('Unable to fetch users:', error);
    throw error;
  }
}

fetchUsers();
